// Writes the browser-side code from the compiled dist/esm/inpage.js to python/src/screenshot_ready/inpage.js,
// so the Python package runs exactly the functions the Node package sends to the page.
// `node scripts/export-inpage.mjs --check` exits 1 when the Python copy is out of date (CI runs it).
import { readFileSync, writeFileSync } from 'node:fs';

const inpage = await import(new URL('../dist/esm/inpage.js', import.meta.url).href);
const target = new URL('../python/src/screenshot_ready/inpage.js', import.meta.url);

const lines = [
  '// Generated by scripts/export-inpage.mjs from src/inpage.ts (compiled). Do not edit by hand: change',
  '// src/inpage.ts and run `npm run build`.',
  '',
];
for (const [name, value] of Object.entries(inpage).sort(([a], [b]) => a.localeCompare(b))) {
  if (typeof value === 'function') continue;
  // One constant per line, as JSON, so the Python side can read the values without a JavaScript parser.
  lines.push(`const ${name} = ${JSON.stringify(value)};`);
}
lines.push('');
for (const [name, value] of Object.entries(inpage).sort(([a], [b]) => a.localeCompare(b))) {
  if (typeof value !== 'function') continue;
  const source = value.toString();
  if (!source.startsWith(`function ${name}(`)) throw new Error(`${name}: expected a plain function declaration`);
  lines.push(source, '');
}
const output = lines.join('\n');

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(target, 'utf8');
  } catch {
    // missing file: reported below
  }
  if (current !== output) {
    console.error('python/src/screenshot_ready/inpage.js is out of date. Run `npm run build` and commit the result.');
    process.exit(1);
  }
  console.log('python/src/screenshot_ready/inpage.js is up to date.');
} else {
  writeFileSync(target, output);
}
